(function(){document.addEventListener("DOMContentLoaded",()=>{const body=document.body;const timeout=parseInt(body.dataset.timeout,10);const logoutUrl=body.dataset.logoutUrl;if(!timeout||!logoutUrl){console.error("Auto-logout: missing data-timeout or data-logout-url on <body>");return;}let timer;function getCookie(name){let cookieValue=null;if(document.cookie&&document.cookie!==""){const cookies=document.cookie.split(";");for(let i=0;i<cookies.length;i++){const cookie=cookies[i].trim();if(cookie.substring(0,name.length+1)===(name+"=")){cookieValue=decodeURIComponent(cookie.substring(name.length+1));break;}}}return cookieValue;}function doLogout(){const form=document.createElement("form");form.method="POST";form.action=logoutUrl;const csrfToken=document.querySelector("[name=csrfmiddlewaretoken]")?.value||getCookie("csrftoken");if(csrfToken){const input=document.createElement("input");input.type="hidden";input.name="csrfmiddlewaretoken";input.value=csrfToken;form.appendChild(input);}document.body.appendChild(form);form.submit();}function resetTimer(){clearTimeout(timer);timer=setTimeout(doLogout,timeout);}["click","mousemove","keydown","scroll","touchstart"].forEach(evt=>{document.addEventListener(evt,resetTimer,true);});resetTimer();});})();
